import React from 'react';
import { AnalysisResult, ModelMetrics, AttackStatistics } from '../types';

interface AnalysisResultsProps {
    analysisResult?: AnalysisResult;
    metrics?: ModelMetrics;
    statistics?: AttackStatistics;
}

const StatCard: React.FC<{
    title: string;
    value: string | number;
    subtext?: string;
}> = ({ title, value, subtext }) => (
    <div className="stat-card">
        <p style={{ color: 'var(--text-secondary)', marginBottom: '8px', fontSize: '0.875rem' }}>
            {title}
        </p>
        <p className="stat-card-value">
            {value}
        </p>
        {subtext && (
            <p className="stat-card-trend">
                {subtext}
            </p>
        )}
    </div>
);

const MetricBar: React.FC<{ label: string; value: number }> = ({
    label,
    value,
}) => (
    <div style={{ marginBottom: '24px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
            <p style={{ fontWeight: 'bold', fontSize: '0.875rem', color: 'var(--text-primary)' }}>
                {label}
            </p>
            <p style={{ color: 'var(--primary-red)', fontWeight: 'bold', fontSize: '0.875rem' }}>
                {(value * 100).toFixed(2)}%
            </p>
        </div>
        <div className="progress-bar">
            <div 
                className="progress-bar-fill" 
                style={{ 
                    width: `${value * 100}%`,
                }}
            ></div>
        </div>
    </div>
);

const AnalysisResults: React.FC<AnalysisResultsProps> = ({
    analysisResult,
    metrics,
    statistics,
}) => {
    if (!analysisResult && !metrics && !statistics) {
        return (
            <div style={{ textAlign: 'center', paddingTop: '48px', paddingBottom: '48px' }}>
                <p style={{ color: 'var(--text-secondary)', fontSize: '1rem' }}>
                    No analysis results available. Please upload and analyze a dataset first.
                </p>
            </div>
        );
    }

    return (
        <div>
            {/* Key Metrics Cards */}
            <div className="grid grid-4" style={{ marginBottom: '32px' }}>
                {analysisResult && (
                    <>
                        <StatCard
                            title="Total Records"
                            value={analysisResult.total_records}
                        />
                        <StatCard
                            title="Attacks Detected"
                            value={analysisResult.attacks_detected}
                            subtext={`${analysisResult.attack_percentage}% of data`}
                        />
                        <StatCard
                            title="Normal Records"
                            value={analysisResult.normal_records}
                            subtext={`${(100 - analysisResult.attack_percentage).toFixed(2)}% of data`}
                        />
                        <StatCard
                            title="Attack Rate"
                            value={`${analysisResult.attack_percentage}%`}
                        />
                    </>
                )}
            </div>

            {/* Model Metrics */}
            {metrics && (
                <div className="card" style={{ marginBottom: '32px' }}>
                    <h3 className="card-header">
                        Model Performance Metrics
                    </h3>
                    <MetricBar label="Accuracy" value={metrics.accuracy} />
                    <MetricBar label="Precision" value={metrics.precision} />
                    <MetricBar label="Recall" value={metrics.recall} />
                    <MetricBar label="F1 Score" value={metrics.f1_score} />
                </div>
            )}

            {/* Attack Statistics */}
            {statistics && (
                <div className="card">
                    <h3 className="card-header">
                        Attack Statistics
                    </h3>

                    <div style={{ marginBottom: '24px', padding: '16px', backgroundColor: 'rgba(204, 41, 54, 0.08)', borderRadius: '4px', border: '1px solid rgba(204, 41, 54, 0.2)' }}>
                        <p style={{ color: 'var(--text-secondary)', fontSize: '0.875rem' }}>
                            Detection Rate
                        </p>
                        <p style={{ color: 'var(--primary-red)', fontWeight: 'bold', fontSize: '1.5rem' }}>
                            {statistics.detection_rate}%
                        </p>
                    </div>

                    <h4 style={{ fontWeight: 'bold', marginBottom: '16px', fontSize: '0.9rem', color: 'var(--text-primary)' }}>
                        Attack Types Breakdown:
                    </h4>

                    {Object.keys(statistics.attack_types).length > 0 ? (
                        <div className="table-container">
                            <table className="table">
                                <thead>
                                    <tr>
                                        <th>Attack Type</th>
                                        <th align="right">Count</th>
                                        <th align="right">Percentage</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {Object.entries(statistics.attack_types).map(([type, count]) => {
                                        const percentage =
                                            statistics.attacks_detected > 0
                                                ? ((count / statistics.attacks_detected) * 100).toFixed(2)
                                                : 0;
                                        return (
                                            <tr key={type}>
                                                <td style={{ fontWeight: 500 }}>{type}</td>
                                                <td align="right">{count}</td>
                                                <td align="right">
                                                    <span style={{
                                                        display: 'inline-block',
                                                        paddingLeft: '12px',
                                                        paddingRight: '12px',
                                                        paddingTop: '4px',
                                                        paddingBottom: '4px',
                                                        backgroundColor: 'rgba(204, 41, 54, 0.15)',
                                                        color: 'var(--primary-red)',
                                                        borderRadius: '4px',
                                                        fontWeight: 'bold',
                                                        fontSize: '0.875rem',
                                                    }}>
                                                        {percentage}%
                                                    </span>
                                                </td>
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                    ) : (
                        <p style={{ color: 'var(--text-secondary)', fontSize: '0.875rem' }}>
                            No specific attack types detected in the dataset.
                        </p>
                    )}
                </div>
            )}
        </div>
    );
};

export default AnalysisResults;
